const metrics = $json;
const subVertical = `${metrics.subVertical ?? 'other'}`.toLowerCase();
const recurringEligible = subVertical === 'pest-control' || subVertical === 'landscaping';
const bookingRate = metrics.newLeads ? Math.round((metrics.bookedJobs / metrics.newLeads) * 100) : 0;
const recurringSection = recurringEligible
  ? `Recurring renewals due: ${metrics.recurringRenewalsDue ?? 0}
Recurring reactivations sent: ${metrics.recurringReactivationsSent ?? 0}`
  : `Recurring service reactivation: not applicable for ${subVertical}`;
const digest = `Home Services Weekly Digest
Sub-vertical: ${subVertical}
Period: ${metrics.period}

New leads: ${metrics.newLeads}
Booked jobs: ${metrics.bookedJobs} (${bookingRate}%)
Missed calls: ${metrics.missedCalls}
Safety-branch escalations: ${metrics.safetyEscalations ?? 0}
Stale estimates: ${metrics.staleEstimates}
Review opportunities: ${metrics.reviewOpportunities}
Reviews requested: ${metrics.reviewsRequested}

${recurringSection}

Workflow failures: ${metrics.workflowFailures}`;
return [{ json: { ...metrics, recurringEligible, bookingRate, digest } }];
